# -*- coding: utf-8 -*-
"""Banco de ejercicios UD02 · bloques 3 y 4 (ejercicios 13-25)."""
from chen_eer import *

EJS = []


def ej(**kw):
    EJS.append(kw)


# ============================================================ BLOQUE 3
ej(n=13, titulo="Transporte urbano: líneas, paradas y turnos", nivel=3, dur="1-2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + análisis de la ternaria",
   objetivo="Introducir una relación **ternaria** junto a una entidad débil y una N:M reflexiva con atributos.",
   contexto="La empresa municipal de autobuses gestiona su red, su flota y los turnos de conducción.",
   enun=["De las **líneas** se conoce el código (L1, L5…), el nombre del trayecto y la frecuencia de paso en minutos.",
         "Cada línea hace sus paradas en un orden. Cada **parada** se identifica por su número de orden dentro de la línea (1, 2, 3…); se guarda el nombre de la calle o marquesina y si tiene pantalla de información.",
         "Entre líneas se habilitan **transbordos**, con el tiempo estimado a pie entre las dos líneas conectadas.",
         "De los **autobuses** se guarda la matrícula, el modelo y la capacidad de pasajeros de pie. De los **conductores**, el DNI, el nombre y el tipo de licencia. Un conductor conduce un autobús asignado a una línea en un **turno** de trabajo concreto."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Modela *conduce* como relación **ternaria** (conductor, autobús, línea) con el atributo `turno`. Indica su cardinalidad (N:M:P) y explica qué pasaría con tres relaciones binarias.",
           "Razona por qué `PARADA` es débil y por qué *transbordo* es reflexiva con atributo.",
           "Escribe dos restricciones: una sobre el número mínimo de paradas y otra sobre los turnos."],
   comp=["*Conduce* es un único rombo conectado a tres entidades.",
         "`PARADA` es débil de `LÍNEA`; su discriminador es el número de orden.",
         "*Transbordo* tiene el atributo `tiempo_a_pie`.",
         "Has explicado qué información se pierde con tres binarias."],
   err=["Dibujar tres relaciones binarias (conductor–autobús, autobús–línea, conductor–línea): no sabrías quién conducía qué autobús en qué línea.",
        "Colocar `turno` en `CONDUCTOR`. El turno depende de la combinación de los tres."],
   pista=("Pista: ¿ternaria o binarias?",
          "Si el hecho «el conductor C conduce el autobús A en la línea L en el turno T» no se puede reconstruir a partir de tres hechos parciales, necesitas la ternaria. Prueba con dos conductores, dos autobuses y dos líneas."),
   amp="El transbordo se produce realmente **entre paradas**, no entre líneas. Redibuja la relación entre `PARADA` y `PARADA` y razona cómo se identifica ahora.",
   dec=["*Conduce* es ternaria porque el hecho involucra a las tres entidades a la vez y no se puede descomponer.",
        "*Tiene* (línea–parada) es identificadora; una línea tiene al menos dos paradas.",
        "*Transbordo* es una N:M reflexiva con `tiempo_a_pie`; los roles son los dos extremos de la conexión."],
   sup=["Cada línea tiene como mínimo dos paradas: (2,N).",
        "Un autobús puede cambiar de línea de un turno a otro.",
        "El tiempo de transbordo es simétrico entre líneas.",
        "Un conductor no puede conducir dos autobuses en el mismo turno (restricción textual)."],
   model=Model("Transporte urbano: líneas, paradas y turnos",
               "LÍNEA tiene PARADA (débil). LÍNEA se conecta con LÍNEA mediante transbordo. CONDUCTOR, AUTOBÚS y LÍNEA se relacionan en conduce (ternaria) con el turno.",
               [E("LÍNEA", [K("cód_línea"), A("trayecto"), A("frecuencia_min")]),
                E("PARADA", [KP("nº_orden"), A("calle"), A("pantalla")], weak=True),
                E("AUTOBÚS", [K("matrícula"), A("modelo"), A("capacidad_pie")]),
                E("CONDUCTOR", [K("dni"), A("nombre"), A("tipo_licencia")])],
               [R("tiene", [("LÍNEA", "(1,1)", None), ("PARADA", "(2,N)", None)], ident=True),
                R("transbordo", [("LÍNEA", "(0,N)", "origen"), ("LÍNEA", "(0,N)", "destino")], [A("tiempo_a_pie")]),
                R("conduce", [("CONDUCTOR", "(0,N)", None), ("AUTOBÚS", "(0,N)", None), ("LÍNEA", "(0,N)", None)], [KP("turno")])]))

ej(n=14, titulo="Federación deportiva: equipos, partidos e incidencias", nivel=3, dur="1-2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + restricciones",
   objetivo="Modelar **dos relaciones entre las mismas entidades** (local y visitante), una relación circular (capitán) y una entidad débil con discriminador compuesto.",
   contexto="Una federación deportiva informatiza el control de sus competiciones oficiales.",
   enun=["De los **equipos** se conoce el código, el nombre del club y la ciudad. De los **jugadores**, el número de ficha federativa, el DNI, el nombre y el dorsal. Un jugador pertenece a un único equipo y cada equipo designa a uno de sus jugadores como **capitán**.",
         "De los **partidos** se guarda el código, la fecha y hora y la jornada. En cada partido se enfrentan dos equipos distintos: uno como **local** y otro como **visitante**.",
         "En el acta de cada partido se registran las **incidencias**. Cada incidencia se identifica por el minuto de juego y un número de secuencia dentro del partido; se anota el tipo (*gol*, *tarjeta amarilla*, *expulsión* o *sustitución*) y el jugador que protagoniza la acción. Si se anula un partido, se eliminan las incidencias de su acta."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Explica por qué entre `EQUIPO` y `PARTIDO` hay **dos** relaciones y no una con un atributo `rol`.",
           "Escribe el identificador de `INCIDENCIA` y razona por qué el discriminador tiene dos atributos.",
           "Escribe al menos tres restricciones que el diagrama no recoge (capitán del propio equipo, local distinto de visitante, jugador de uno de los dos equipos)."],
   comp=["Hay dos relaciones con roles distintos entre `EQUIPO` y `PARTIDO`.",
         "*Capitán* es 1:1 y distinta de *pertenece*.",
         "`INCIDENCIA` es débil de `PARTIDO` con discriminador (minuto, número de secuencia).",
         "Has escrito la restricción «el jugador pertenece a uno de los equipos del partido»."],
   err=["Relacionar `PARTIDO` con `EQUIPO` mediante una sola N:M: no distingues quién juega en casa.",
        "Usar solo el minuto como discriminador: puede haber dos incidencias en el mismo minuto."],
   amp="La federación quiere guardar los **jugadores convocados** en cada partido y los minutos que juega cada uno. ¿Qué relación añades y con qué atributos? ¿Cómo se relaciona con la incidencia?",
   dec=["*Local* y *visitante* son dos relaciones 1:N entre `EQUIPO` y `PARTIDO`: dan información distinta.",
        "*Capitán* (1:1) y *pertenece* (1:N) son relaciones distintas entre `JUGADOR` y `EQUIPO`.",
        "`INCIDENCIA` es débil de `PARTIDO`: (código de partido, minuto, nº de secuencia)."],
   sup=["Todo partido tiene equipo local y visitante: (1,1) en cada relación.",
        "Una incidencia la protagoniza un único jugador.",
        "El capitán pertenece al equipo que capitanea (restricción textual).",
        "El equipo local y el visitante de un partido son distintos (restricción textual)."],
   model=Model("Federación deportiva: equipos, partidos e incidencias",
               "JUGADOR pertenece a EQUIPO y un jugador es capitán. EQUIPO es local o visitante en PARTIDO. PARTIDO registra INCIDENCIA (débil) protagonizada por JUGADOR.",
               [E("EQUIPO", [K("cód_equipo"), A("club"), A("ciudad")]),
                E("JUGADOR", [K("nº_ficha"), A("dni"), A("nombre"), A("dorsal")]),
                E("PARTIDO", [K("cód_partido"), A("fecha_hora"), A("jornada")]),
                E("INCIDENCIA", [KP("minuto"), KP("nº_secuencia"), A("tipo")], weak=True)],
               [R("pertenece a", [("EQUIPO", "(1,1)", None), ("JUGADOR", "(1,N)", None)]),
                R("capitán", [("JUGADOR", "(1,1)", None), ("EQUIPO", "(0,1)", None)]),
                R("local", [("EQUIPO", "(1,1)", None), ("PARTIDO", "(0,N)", None)]),
                R("visitante", [("EQUIPO", "(1,1)", None), ("PARTIDO", "(0,N)", None)]),
                R("registra", [("PARTIDO", "(1,1)", None), ("INCIDENCIA", "(0,N)", None)], ident=True),
                R("protagoniza", [("JUGADOR", "(1,1)", None), ("INCIDENCIA", "(0,N)", None)])]))

ej(n=15, titulo="Red de gimnasios: salas, reservas y entrenadores", nivel=3, dur="1-2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + restricciones",
   objetivo="Gestionar varias relaciones N:M con atributos repetibles junto a una entidad débil y una supervisión reflexiva.",
   contexto="Una cadena de gimnasios gestiona sus centros, sus socios y los entrenamientos personalizados.",
   enun=["De cada **gimnasio** se conoce el código, el nombre comercial, la dirección, la ciudad y la superficie en m².",
         "Cada gimnasio dispone de **salas**. Cada sala se identifica por un número o letra propio del gimnasio (101, Sala A…); se guarda el tipo de actividad (*musculación*, *cardio*, *pilates*, *spinning*) y el aforo máximo.",
         "De los **socios** se almacena el número, el DNI, el nombre, los apellidos, el teléfono y la fecha de alta. Un socio está inscrito en un gimnasio principal, pero puede reservar plaza en las salas de cualquier centro de la cadena (se registra la fecha, la hora y la plaza).",
         "De los **entrenadores** se conoce el código de empleado, el nombre, la especialidad y la titulación. Cada entrenador trabaja en un gimnasio y diseña **rutinas** para los socios, con la fecha de asignación y el objetivo. En cada gimnasio, un **director técnico** coordina al resto de entrenadores."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Distingue las dos relaciones entre `SOCIO` y `GIMNASIO`/`SALA`: la inscripción y la reserva. Justifica sus cardinalidades.",
           "Identifica qué atributos de las dos relaciones N:M permiten que se repitan entre las mismas entidades.",
           "Escribe tres restricciones textuales (aforo, un único director por gimnasio, reservas solapadas)."],
   comp=["`SALA` es débil de `GIMNASIO`.",
         "*Reserva* conecta `SOCIO` con `SALA` y la fecha y la hora forman parte de su identificación.",
         "*Diseña* es N:M con `fecha_asignación` y `objetivo`.",
         "*Dirige* es una relación reflexiva sobre `ENTRENADOR`."],
   err=["Relacionar `SOCIO` con `GIMNASIO` para las reservas. La reserva se hace sobre una sala concreta.",
        "Olvidar que un socio puede reservar la misma sala muchas veces."],
   amp="Las reservas de clase **tienen un entrenador** responsable. ¿La reserva pasa a ser una ternaria o puede resolverse con una binaria adicional? Razona con el aforo y la sesión.",
   dec=["La inscripción (socio → gimnasio) es 1:N; la reserva es N:M entre `SOCIO` y `SALA` con fecha, hora y plaza.",
        "`SALA` se identifica por (código de gimnasio, número de sala).",
        "El director técnico es un entrenador que coordina a otros: relación reflexiva 1:N con roles."],
   sup=["Un gimnasio tiene al menos una sala.",
        "Un entrenador trabaja en un único gimnasio.",
        "En cada gimnasio hay un solo director técnico (restricción textual).",
        "El número de reservas de una sala en una franja no supera su aforo (restricción textual)."],
   model=Model("Red de gimnasios: salas, reservas y entrenadores",
               "GIMNASIO dispone de SALA (débil). SOCIO se inscribe en GIMNASIO y reserva SALA. ENTRENADOR trabaja en GIMNASIO, diseña rutinas para SOCIO y es dirigido por otro ENTRENADOR.",
               [E("GIMNASIO", [K("cód_centro"), A("nombre"), A("dirección"), A("ciudad"), A("superficie_m2")]),
                E("SALA", [KP("nº_sala"), A("actividad"), A("aforo")], weak=True),
                E("SOCIO", [K("nº_socio"), A("dni"), A("nombre"), A("apellidos"), A("teléfono"), A("fecha_alta")]),
                E("ENTRENADOR", [K("cód_empleado"), A("nombre"), A("especialidad"), A("titulación")])],
               [R("dispone de", [("GIMNASIO", "(1,1)", None), ("SALA", "(1,N)", None)], ident=True),
                R("se inscribe en", [("GIMNASIO", "(1,1)", None), ("SOCIO", "(0,N)", None)]),
                R("reserva", [("SOCIO", "(0,N)", None), ("SALA", "(0,N)", None)], [KP("fecha"), KP("hora"), A("plaza")]),
                R("trabaja en", [("ENTRENADOR", "(1,N)", None), ("GIMNASIO", "(1,1)", None)]),
                R("diseña", [("ENTRENADOR", "(0,N)", None), ("SOCIO", "(0,N)", None)], [KP("fecha_asignación"), A("objetivo")]),
                R("dirige", [("ENTRENADOR", "(0,1)", "director"), ("ENTRENADOR", "(0,N)", "entrenador")])]))

ej(n=16, titulo="Repostería PAVA S.A.: recetas, formatos, pedidos y competencia", nivel=3, dur="2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + diccionario de datos",
   objetivo="Resolver un caso con siete entidades, una composición con porcentajes y un formato dependiente del producto.",
   contexto="Una gran empresa de dulces necesita una base de datos centralizada para su producción, ventas y promociones.",
   enun=["La empresa elabora productos a partir de **ingredientes**. De cada ingrediente se conoce el nombre (único), la cantidad de vitaminas A, B y C por cada 100 g, las calorías y el coste por kilo.",
         "Con ellos fabrica **productos** («Filipondios», «Barridulces»…), conocidos por su nombre comercial. Interesa la composición de cada producto y el **porcentaje** de cada ingrediente en la receta.",
         "Cada producto se comercializa en **formatos** de peso (40 g, 150 g, 250 g…), y cada formato tiene un precio de venta.",
         "De los **clientes** se guarda el CIF, el nombre, la dirección, la población, la provincia y el teléfono. Los clientes hacen **pedidos** de unidades de productos en formatos concretos (200 unidades de Barridulces en formato de 250 g).",
         "La empresa prevé las **promociones** del año («2x1», «Vale descuento»). Cada tipo de promoción se pone en marcha una vez al año, con fecha de inicio, fecha de fin y la cantidad máxima de productos de cada formato que pueden beneficiarse.",
         "Por último, se registran los **productos competidores** (nombre comercial único, marca y año de lanzamiento), vinculando cada uno al producto de la empresa al que más se parece."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Decide si el formato es una entidad débil de `PRODUCTO` o una entidad independiente. Justifícalo con un ejemplo (40 g de Barridulces frente a 40 g de Filipondios).",
           "Elabora el **diccionario de datos** de `INGREDIENTE` y de la relación de composición.",
           "Escribe tres restricciones: suma de porcentajes, cantidad máxima de promoción y fechas."],
   comp=["La composición es una N:M con atributo `porcentaje`.",
         "El formato depende del producto: `FORMATO` es una entidad débil.",
         "El pedido se relaciona con el **formato**, no solo con el producto.",
         "*Se parece a* es 1:N desde el producto hacia los competidores."],
   err=["Relacionar `PEDIDO` con `PRODUCTO` sin indicar el formato. No sabrías qué se ha pedido.",
        "Poner el precio en `PRODUCTO`: cada formato tiene el suyo."],
   amp="El **precio** de cada formato cambia con el tiempo y se quiere conservar el histórico. ¿Qué entidad o atributo añadirías? ¿Dónde se guardaría el precio con el que se vendió cada pedido?",
   dec=["`FORMATO` es débil de `PRODUCTO`: (nombre comercial, peso).",
        "*Se compone de* es N:M con `porcentaje`; el porcentaje depende de la pareja producto-ingrediente.",
        "*Solicita* relaciona `PEDIDO` con `FORMATO` y guarda las unidades; *se aplica a* lo hace con `PROMOCIÓN` y guarda la cantidad máxima."],
   sup=["Todo producto tiene al menos un ingrediente: (1,N).",
        "Un competidor se parece a un solo producto de la empresa.",
        "Los porcentajes de una receta suman 100 (restricción textual).",
        "La fecha de fin de la promoción no es anterior a la de inicio (restricción textual)."],
   model=Model("Repostería PAVA S.A.",
               "INGREDIENTE forma parte de PRODUCTO con un porcentaje. PRODUCTO tiene FORMATO (débil). CLIENTE hace PEDIDO que solicita FORMATO. PROMOCIÓN se aplica a FORMATO. COMPETIDOR se parece a PRODUCTO.",
               [E("INGREDIENTE", [K("nombre"), A("vitaminas_A_B_C"), A("calorías"), A("coste_kg")]),
                E("PRODUCTO", [K("nombre_comercial")]),
                E("FORMATO", [KP("peso_g"), A("precio_venta")], weak=True),
                E("CLIENTE", [K("cif"), A("nombre"), C("dirección", "calle", "población", "provincia"), A("teléfono")]),
                E("PEDIDO", [K("nº_pedido"), A("fecha")]),
                E("PROMOCIÓN", [K("tipo"), A("fecha_inicio"), A("fecha_fin")]),
                E("COMPETIDOR", [K("nombre_comercial"), A("marca"), A("año_lanzamiento")])],
               [R("se compone de", [("INGREDIENTE", "(1,N)", None), ("PRODUCTO", "(0,N)", None)], [A("porcentaje")]),
                R("tiene", [("PRODUCTO", "(1,1)", None), ("FORMATO", "(1,N)", None)], ident=True),
                R("hace", [("CLIENTE", "(1,1)", None), ("PEDIDO", "(0,N)", None)]),
                R("solicita", [("PEDIDO", "(0,N)", None), ("FORMATO", "(1,N)", None)], [A("unidades")]),
                R("se aplica a", [("PROMOCIÓN", "(0,N)", None), ("FORMATO", "(0,N)", None)], [A("cantidad_máxima")]),
                R("se parece a", [("COMPETIDOR", "(0,N)", None), ("PRODUCTO", "(1,1)", None)])]))

ej(n=17, titulo="Planta industrial: lista de materiales e inspecciones", nivel=3, dur="2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + restricciones",
   objetivo="Modelar una estructura de **lista de materiales (BOM)** con una N:M reflexiva y detectar restricciones de integridad que el diagrama no recoge (ciclos y borrado).",
   contexto="Una planta de maquinaria pesada gestiona su proceso de producción y sus controles de calidad.",
   enun=["De las **fábricas** se conoce el código, la ubicación y el teléfono. Cada fábrica alberga varias **líneas de montaje**. El código de línea es correlativo dentro de cada fábrica (la línea 1 de Valencia y la línea 1 de Sevilla son distintas) y se guarda la denominación.",
         "De las **piezas** se registra el código, el nombre, el peso en gramos y el coste estándar. Una pieza se ensambla a partir de otras piezas componentes y una pieza puede formar parte de muchas piezas superiores. De cada componente interesa la **cantidad** de unidades necesarias. Cada pieza se fabrica en una línea de montaje.",
         "Cada pieza pasa **inspecciones** de calidad. Cada inspección se identifica con un número dentro de la pieza y guarda la fecha, el resultado (*aprobado* o *rechazado*) y las observaciones. Si una pieza se descataloga, sus inspecciones se eliminan automáticamente."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Explica la relación reflexiva *compone* con sus dos roles y su atributo.",
           "Identifica las **dos** entidades débiles y escribe sus identificadores completos.",
           "Escribe las restricciones: ausencia de ciclos en la lista de materiales, borrado en cascada y dominio del resultado."],
   comp=["*Compone* es una N:M reflexiva con el atributo `cantidad`.",
         "`LÍNEA` e `INSPECCIÓN` son entidades débiles.",
         "La pieza se relaciona con la línea de montaje (que a su vez depende de la fábrica).",
         "Entre las restricciones aparece «una pieza no puede contenerse a sí misma, directa o indirectamente»."],
   err=["Dar a `LÍNEA` un código global: el enunciado dice que es correlativo por fábrica.",
        "Modelar la lista de materiales con una relación 1:N: una pieza componente participa en muchos ensamblajes."],
   amp="Algunas piezas se **compran a proveedores** en lugar de fabricarse. ¿Cómo modelarías esta distinción? Plantea una especialización de `PIEZA` y decide si es total o parcial, disyunta o solapada.",
   dec=["`LÍNEA` se identifica por (código de fábrica, código de línea) e `INSPECCIÓN` por (código de pieza, número).",
        "*Compone* es una reflexiva N:M: una pieza tiene muchos componentes y es componente de muchas piezas.",
        "La pieza se fabrica en una línea: relación N:1 con la entidad débil."],
   sup=["Todas las piezas se fabrican en una línea: (1,1).",
        "Una pieza simple (sin componentes) es válida.",
        "No se admiten ciclos en la lista de materiales (restricción textual).",
        "Al eliminar una pieza se eliminan sus inspecciones (borrado en cascada)."],
   model=Model("Planta industrial: lista de materiales e inspecciones",
               "FÁBRICA alberga LÍNEA (débil). PIEZA se fabrica en una LÍNEA. PIEZA se compone de PIEZA con una cantidad. PIEZA se inspecciona en INSPECCIÓN (débil).",
               [E("FÁBRICA", [K("cód_fábrica"), A("ubicación"), A("teléfono")]),
                E("LÍNEA", [KP("cód_línea"), A("denominación")], weak=True),
                E("PIEZA", [K("cód_pieza"), A("nombre"), A("peso_g"), A("coste_estándar")]),
                E("INSPECCIÓN", [KP("nº_inspección"), A("fecha"), A("resultado"), A("observaciones")], weak=True)],
               [R("alberga", [("FÁBRICA", "(1,1)", None), ("LÍNEA", "(1,N)", None)], ident=True),
                R("se fabrica en", [("PIEZA", "(0,N)", None), ("LÍNEA", "(1,1)", None)]),
                R("compone", [("PIEZA", "(0,N)", "ensamblada"), ("PIEZA", "(0,N)", "componente")], [A("cantidad")]),
                R("se inspecciona", [("PIEZA", "(1,1)", None), ("INSPECCIÓN", "(0,N)", None)], ident=True)]))

ej(n=18, titulo="Comandancia de Starship Troopers", nivel=3, dur="2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + restricciones",
   objetivo="Combinar siete relaciones con cardinalidades máximas concretas, atributos de N:M y una jerarquía reflexiva.",
   contexto="La comandancia de la fuerza de defensa quiere registrar su operativa interna.",
   enun=["De los **troopers** se conoce el número de placa, el DNI, el nombre, la categoría y la función (piloto, agente…). Cada trooper tiene un único **jefe** directo y un trooper puede ser jefe de varios subordinados.",
         "El arsenal contiene **armas** con código único, clase y nombre. Un trooper puede usar varias armas; interesa la **habilidad** (de 1 a 10) de cada trooper con cada arma.",
         "De los **bichos** capturados se conoce el identificador, la raza, la localización de origen y el peso. Un bicho es detenido por uno o varios troopers y se guarda la **fecha de detención**. El mismo trooper puede detener al mismo bicho en fechas distintas.",
         "Cada bicho que permanece en la comandancia se encierra en una **mazmorra** (código y ubicación). En una mazmorra puede haber varios bichos, **nunca más de cuatro**.",
         "Los bichos participan en **delitos** (número de asalto y juzgado instructor), y se anota el **cargo principal** de cada bicho en cada delito. Uno o varios troopers investigan cada delito."],
   tareas=["Dibuja el diagrama EER en notación de Chen.",
           "Escribe las cardinalidades (mín, máx) de las siete relaciones y justifica la de la mazmorra.",
           "Indica qué atributos pertenecen a relaciones N:M y por qué (habilidad, fecha de detención, cargo principal).",
           "Escribe las restricciones: la habilidad entre 1 y 10, y el máximo de cuatro bichos por mazmorra."],
   comp=["La jerarquía de jefes es una reflexiva 1:N.",
         "`cargo_principal` está en la relación *implicado en*.",
         "La mazmorra tiene máximo 4 bichos en la cardinalidad.",
         "`fecha_detención` forma parte de la identificación de *detiene*."],
   err=["Poner `cargo_principal` en `BICHO`: un bicho puede estar implicado en varios delitos con cargos distintos.",
        "Expresar «máximo cuatro» solo en el texto y no en la cardinalidad."],
   amp="Cada trooper tiene una **especialidad** (piloto, agente, médico…) con datos propios. Plantea una **especialización** de `TROOPER`, decide si es total o parcial, disyunta o solapada, y redibuja la parte afectada.",
   dec=["*Jefe* es una reflexiva 1:N; un trooper sin jefe es la cúspide de la cadena.",
        "*Usa*, *detiene*, *implicado en* e *investiga* son N:M. Los tres primeros llevan atributos.",
        "*Encierra* es 1:N con máximo 4 en el lado del bicho: (0,4)."],
   sup=["Un bicho puede estar capturado y no encerrado: (0,1) mazmorra.",
        "Un delito tiene al menos un bicho implicado.",
        "La habilidad es un entero entre 1 y 10 (restricción de dominio).",
        "Una mazmorra no aloja a más de cuatro bichos a la vez (restricción textual)."],
   model=Model("Comandancia de Starship Troopers",
               "TROOPER tiene jefe TROOPER, usa ARMA, detiene BICHO e investiga DELITO. MAZMORRA encierra BICHO. BICHO está implicado en DELITO.",
               [E("TROOPER", [K("nº_placa"), A("dni"), A("nombre"), A("categoría"), A("función")]),
                E("ARMA", [K("cód_arma"), A("clase"), A("nombre")]),
                E("BICHO", [K("id_bicho"), A("raza"), A("origen"), A("peso")]),
                E("MAZMORRA", [K("cód_mazmorra"), A("ubicación")]),
                E("DELITO", [K("nº_asalto"), A("juzgado")])],
               [R("jefe", [("TROOPER", "(0,1)", "jefe"), ("TROOPER", "(0,N)", "subordinado")]),
                R("usa", [("TROOPER", "(0,N)", None), ("ARMA", "(0,N)", None)], [A("habilidad")]),
                R("detiene", [("TROOPER", "(1,N)", None), ("BICHO", "(0,N)", None)], [KP("fecha_detención")]),
                R("encierra", [("MAZMORRA", "(0,1)", None), ("BICHO", "(0,4)", None)]),
                R("implicado en", [("BICHO", "(1,N)", None), ("DELITO", "(0,N)", None)], [A("cargo_principal")]),
                R("investiga", [("TROOPER", "(1,N)", None), ("DELITO", "(0,N)", None)])]))

ej(n=19, titulo="Torneo de Quidditch: jugadores especializados", nivel=3, dur="2 sesiones",
   ra="RA6: a, d, e, h", entrega="Diagrama EER + clasificación de la jerarquía",
   objetivo="Ampliar un modelo conocido (ejercicio 14) con una **especialización total y disyunta** con atributos propios.",
   contexto="Una liga mágica celebra un torneo oficial. El modelo parte del de la federación deportiva, pero ahora los jugadores se especializan por puesto.",
   enun=["De cada **equipo** se registra el código, el nombre del club, la casa o colegio al que representa y el año de fundación. Los **jugadores** (número de carné, nombre y apellidos) pertenecen a un único equipo y cada equipo designa a uno como **capitán**.",
         "Cada jugador ocupa un único puesto y de cada puesto se guardan estadísticas propias: los **guardianes**, las paradas; los **golpeadores**, las bludgers golpeadas; los **cazadores**, los goles marcados; los **buscadores**, las capturas de snitch.",
         "De los **partidos** se conoce el código, el estadio, la fecha y hora y el **árbitro** asignado (código y nombre). En cada partido compiten un equipo local y uno visitante.",
         "Durante el partido se registran **incidencias** (infracciones y penaltis), identificadas por el minuto y un número de secuencia dentro del partido. Se anotan el tipo de falta, la puntuación otorgada y el jugador sancionado."],
   tareas=["Dibuja el diagrama EER en notación de Chen con la jerarquía de jugadores.",
           "Clasifica la jerarquía (total o parcial, disyunta o solapada) y justifícalo con una frase del enunciado.",
           "¿Qué ocurre con el atributo `posición` que aparecía en el ejercicio 14? ¿Sigue haciendo falta?",
           "Escribe las restricciones: capitán del propio equipo, local distinto de visitante, árbitro sin vínculo con los equipos."],
   comp=["La especialización es **total y disyunta** y se dibuja con el círculo `d` y doble línea hacia la superclase.",
         "Los atributos comunes están en `JUGADOR` y las estadísticas, en cada subclase.",
         "El árbitro es una entidad relacionada con el partido.",
         "`INCIDENCIA` es débil de `PARTIDO`."],
   err=["Repetir los atributos comunes (nombre, carné…) en cada subclase.",
        "Mantener un atributo `posición` además de la especialización: duplica la información y puede contradecirse."],
   amp="Algunos jugadores pueden ocupar **dos puestos** en la misma temporada (cazador y buscador). ¿Qué cambia en la clasificación de la jerarquía? ¿Cómo la dibujarías?",
   dec=["Hay cuatro subclases con una sola jerarquía **total y disyunta**: cada jugador ocupa un puesto y solo uno.",
        "El atributo `posición` desaparece: la pertenencia a una subclase la expresa.",
        "El resto del modelo (capitán, local, visitante, incidencias) es el del ejercicio 14, más la entidad `ÁRBITRO`."],
   sup=["Todo jugador tiene un puesto: especialización total.",
        "Un partido tiene un único árbitro: (1,1).",
        "El jugador sancionado pertenece a uno de los dos equipos del partido (restricción textual).",
        "El capitán pertenece a su equipo (restricción textual)."],
   model=Model("Torneo de Quidditch: jugadores especializados",
               "JUGADOR se especializa (d, total) en GUARDIÁN, GOLPEADOR, CAZADOR y BUSCADOR. EQUIPO tiene JUGADOR y capitán, juega PARTIDO como local y visitante. ÁRBITRO arbitra PARTIDO. PARTIDO registra INCIDENCIA.",
               [E("EQUIPO", [K("cód_equipo"), A("club"), A("casa_colegio"), A("año_fundación")]),
                E("JUGADOR", [K("nº_carné"), A("nombre"), A("apellidos")]),
                E("GUARDIÁN", [A("paradas")]), E("GOLPEADOR", [A("bludgers")]),
                E("CAZADOR", [A("goles")]), E("BUSCADOR", [A("snitch")]),
                E("PARTIDO", [K("cód_partido"), A("estadio"), A("fecha_hora")]),
                E("ÁRBITRO", [K("cód_árbitro"), A("nombre")]),
                E("INCIDENCIA", [KP("minuto"), KP("nº_secuencia"), A("tipo_falta"), A("puntos")], weak=True)],
               [R("pertenece a", [("EQUIPO", "(1,1)", None), ("JUGADOR", "(1,N)", None)]),
                R("capitán", [("JUGADOR", "(1,1)", None), ("EQUIPO", "(0,1)", None)]),
                R("local", [("EQUIPO", "(1,1)", None), ("PARTIDO", "(0,N)", None)]),
                R("visitante", [("EQUIPO", "(1,1)", None), ("PARTIDO", "(0,N)", None)]),
                R("arbitra", [("ÁRBITRO", "(1,1)", None), ("PARTIDO", "(0,N)", None)]),
                R("registra", [("PARTIDO", "(1,1)", None), ("INCIDENCIA", "(0,N)", None)], ident=True),
                R("sanciona a", [("JUGADOR", "(1,1)", None), ("INCIDENCIA", "(0,N)", None)])],
               [ISA("JUGADOR", ["GUARDIÁN", "GOLPEADOR", "CAZADOR", "BUSCADOR"], "d", True)]))

